import { formatEuros } from './money.js';
import { lineTotal, lineDiscount, lineAmountAfterDiscount, lineVat, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, lines: Array<{ name: string, qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }> }} invoice
 * @param {{ name: string }} customer - The customer object with at least a name property
 * @returns {string}
 */
export function renderInvoiceText(invoice, customer) {
  const lines = [];

  lines.push(invoice.number || 'DRAFT');
  lines.push(`Customer: ${customer.name}`);

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const discount = lineDiscount(line);
    const qtyStr = String(line.qty).padStart(3, ' ');
    const unitPriceStr = formatEuros(line.unitPrice);
    const totalStr = formatEuros(total);

    if (discount > 0) {
      const discountStr = formatEuros(discount);
      const lineStr = formatEuros(total - discount);
      lines.push(`${qtyStr}x ${line.name} @ ${unitPriceStr} = ${totalStr} - ${discountStr} = ${lineStr}`);
    } else {
      lines.push(`${qtyStr}x ${line.name} @ ${unitPriceStr} = ${totalStr}`);
    }
  }

  const totals = invoiceTotals(invoice);
  if (totals.discount > 0 || totals.vat > 0) {
    const subtotalStr = formatEuros(totals.subtotal);
    lines.push(`Subtotal: ${subtotalStr}`);
    if (totals.discount > 0) {
      const discountStr = formatEuros(totals.discount);
      lines.push(`Discount: -${discountStr}`);
    }
    if (totals.vat > 0) {
      const vatStr = formatEuros(totals.vat);
      lines.push(`VAT: ${vatStr}`);
    }
    lines.push(`Total: ${formatEuros(totals.total)}`);
  } else {
    lines.push(`Total: ${formatEuros(totals.total)}`);
  }

  return lines.join('\n');
}

